<?php namespace App\Services; class OeeCalculator { public function calculate(int $plannedMinutes,int $operatingMinutes,float $idealCycleSeconds,int $totalOutput,int $goodOutput): array { $availability=$plannedMinutes>0?min(1,$operatingMinutes/$plannedMinutes):0; $theoretical=$operatingMinutes>0?($idealCycleSeconds*$totalOutput)/$operatingMinutes:0; $performance=min(1,$theoretical); $quality=$totalOutput>0?min(1,$goodOutput/$totalOutput):0; return ['availability'=>$availability,'performance'=>$performance,'quality'=>$quality,'oee'=>$availability*$performance*$quality]; } }